1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	import { useJsonResource } from '../../ui/useJsonResource';
4	
5	// Projects feature: add a project and pick which client it is for, then list every project showing
6	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
7	// against it, their running total, and a form to add another. Owns its own state; talks to its own
8	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
9	// data-testid anchors follow the spec's conventions.
10	type Client = { id: number; name: string; email: string };
11	type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';
12	type Project = {
13	  id: number;
14	  name: string;
15	  clientId: number;
16	  clientName: string;
17	  archived: boolean;
18	  status: ProjectStatus;
19	};
20	type Invoice = {
21	  id: number;
22	  projectId: number;
23	  amount: number;
24	  amountDue: number;
25	  status: string;
26	  issuedDate: string;
27	  dueDate: string;
28	  discountPct: number;
29	  taxPct: number;
30	};
31	type Task = { id: number; projectId: number; title: string; done: boolean };
32	type Tag = { id: number; name: string };
33	type Note = { id: number; targetType: string; targetId: number; text: string; at: string };
34	
35	type LineItem = {
36	  id: number;
37	  invoiceId: number;
38	  description: string;
39	  qty: number;
40	  unit: string;
41	  unitPrice: number;
42	};
43	
44	type Payment = { id: number; invoiceId: number; amount: number; date: string };
45	
46	function money(amount: number): string {
47	  return `$${Number(amount).toLocaleString('en-US', {
48	    minimumFractionDigits: 2,
49	    maximumFractionDigits: 2,
50	  })}`;
51	}
52	
53	// Budget figures are shown with thousands separators (e.g. $1,000.00) so larger amounts stay
54	// readable at a glance.
55	function moneyGrouped(amount: number): string {
56	  return `$${Number(amount).toLocaleString('en-US', {
57	    minimumFractionDigits: 2,
58	    maximumFractionDigits: 2,
59	  })}`;
60	}
61	
62	type ProjectBudget = { budget: number | null; invoiced: number; remaining: number | null };
63	
64	// One charge line while it is being edited on screen: the fields are held as raw strings so the
65	// inputs stay controlled and the total can recompute live as they change.
66	type EditItem = { id: number; description: string; qty: string; unit: string; unitPrice: string };
67	
68	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
69	// many, price each), the total worked out for you, and a form to add another line. Each line can be
70	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
71	// own line-item state, scoped to the one invoice it is showing.
72	function InvoiceDetail({
73	  invoiceId,
74	  onChange,
75	  onClose,
76	}: {
77	  invoiceId: number;
78	  onChange: () => void;
79	  onClose: () => void;
80	}) {
81	  const [items, setItems] = useState<EditItem[]>([]);
82	  const [description, setDescription] = useState('');
83	  const [qty, setQty] = useState('');
84	  const [unit, setUnit] = useState('');
85	  const [unitPrice, setUnitPrice] = useState('');
86	  const [payments, setPayments] = useState<Payment[]>([]);
87	  const [paymentAmount, setPaymentAmount] = useState('');
88	  const [paymentDate, setPaymentDate] = useState('');
89	  const [status, setStatus] = useState('');
90	  // The percentage discount taken off this invoice's subtotal (0 unless one is set).
91	  const [discountPct, setDiscountPct] = useState(0);
92	  // The percentage sales tax added on top after the discount (0 unless one is set).
93	  const [taxPct, setTaxPct] = useState(0);
94	
95	  // The status is worked out from the payments recorded against the invoice, so re-read it whenever
96	  // a payment is added rather than flipping it by hand. The discount and tax percentages come back
97	  // on the same read.
98	  async function loadStatus() {
99	    const res = await fetch(`/api/invoices/${invoiceId}`);
100	    const inv: Invoice = await res.json();
101	    setStatus(inv.status);
102	    setDiscountPct(Number(inv.discountPct) || 0);
103	    setTaxPct(Number(inv.taxPct) || 0);
104	  }
105	
106	  async function load() {
107	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
108	    const rows: LineItem[] = await res.json();
109	    setItems(
110	      rows.map((li) => ({
111	        id: li.id,
112	        description: li.description,
113	        qty: String(li.qty),
114	        unit: li.unit,
115	        unitPrice: String(li.unitPrice),
116	      })),
117	    );
118	  }
119	
120	  async function loadPayments() {
121	    const res = await fetch(`/api/invoices/${invoiceId}/payments`);
122	    setPayments(await res.json());
123	  }
124	
125	  async function submitPayment(e: React.FormEvent) {
126	    e.preventDefault();
127	    const value = Number(paymentAmount);
128	    if (paymentAmount.trim() === '' || !Number.isFinite(value) || value <= 0) {
129	      return;
130	    }
131	    if (paymentDate.trim() === '') {
132	      return;
133	    }
134	    await fetch(`/api/invoices/${invoiceId}/payments`, {
135	      method: 'POST',
136	      headers: { 'Content-Type': 'application/json' },
137	      body: JSON.stringify({ amount: value, date: paymentDate }),
138	    });
139	    setPaymentAmount('');
140	    setPaymentDate('');
141	    await loadPayments();
142	    await loadStatus();
143	    onChange();
144	  }
145	
146	  useEffect(() => {
147	    void load();
148	    void loadPayments();
149	    void loadStatus();
150	  }, [invoiceId]);
151	
152	  function editField(
153	    id: number,
154	    field: 'description' | 'qty' | 'unit' | 'unitPrice',
155	    value: string,
156	  ) {
157	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
158	  }
159	
160	  function amountOf(li: EditItem): number {
161	    const line = Number(li.qty) * Number(li.unitPrice);
162	    return Number.isFinite(line) ? line : 0;
163	  }
164	
165	  async function save(li: EditItem) {
166	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
167	      return;
168	    }
169	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
170	      method: 'POST',
171	      headers: { 'Content-Type': 'application/json' },
172	      body: JSON.stringify({
173	        description: li.description,
174	        qty: Number(li.qty),
175	        unit: li.unit,
176	        unitPrice: Number(li.unitPrice),
177	      }),
178	    });
179	    await load();
180	    onChange();
181	  }
182	
183	  async function remove(id: number) {
184	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
185	    await load();
186	    onChange();
187	  }
188	
189	  async function submit(e: React.FormEvent) {
190	    e.preventDefault();
191	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
192	      return;
193	    }
194	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
195	      method: 'POST',
196	      headers: { 'Content-Type': 'application/json' },
197	      body: JSON.stringify({
198	        description,
199	        qty: Number(qty),
200	        unit,
201	        unitPrice: Number(unitPrice),
202	      }),
203	    });
204	    setDescription('');
205	    setQty('');
206	    setUnit('');
207	    setUnitPrice('');
208	    await load();
209	    onChange();
210	  }
211	
212	  // The subtotal is the sum of the line items; the discount is that percentage taken off it. Sales
213	  // tax is then added on top of the discounted base (worked out after the discount), and the final
214	  // total is the subtotal less the discount plus that tax.
215	  const subtotal = items.reduce((sum, li) => sum + amountOf(li), 0);
216	  const discount = (subtotal * discountPct) / 100;
217	  const tax = ((subtotal - discount) * taxPct) / 100;
218	  const total = subtotal - discount + tax;
219	
220	  return (
221	    <section data-testid="invoice-detail">
222	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
223	        Back to invoices
224	      </button>
225	
226	      <p data-testid="invoice-status">{status}</p>
227	
228	      <table data-testid="invoice-lineitems-table">
229	        <tbody>
230	          {items.map((li) => (
231	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
232	              <td>
233	                <input
234	                  data-testid="lineitem-description"
235	                  value={li.description}
236	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
237	                />
238	              </td>
239	              <td data-testid="lineitem-qty">{li.qty}</td>
240	              <td data-testid="lineitem-unit">{li.unit}</td>
241	              <td>
242	                <input
243	                  data-testid="lineitem-unitprice"
244	                  value={li.unitPrice}
245	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
246	                />
247	              </td>
248	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
249	              <td>
250	                <button
251	                  data-testid={`lineitem-save-${li.id}`}
252	                  type="button"
253	                  onClick={() => save(li)}
254	                >
255	                  Save
256	                </button>
257	                <button
258	                  data-testid={`lineitem-remove-${li.id}`}
259	                  type="button"
260	                  onClick={() => remove(li.id)}
261	                >
262	                  Remove
263	                </button>
264	              </td>
265	            </tr>
266	          ))}
267	        </tbody>
268	      </table>
269	
270	      <p data-testid="invoice-subtotal">{money(subtotal)}</p>
271	      <p data-testid="invoice-discount">{money(discount)}</p>
272	      <p data-testid="invoice-tax">{money(tax)}</p>
273	      <p data-testid="invoice-amount">{money(total)}</p>
274	
275	      <form data-testid="lineitem-form" onSubmit={submit}>
276	        <input
277	          data-testid="lineitem-form-description"
278	          placeholder="Description"
279	          value={description}
280	          onChange={(e) => setDescription(e.target.value)}
281	        />
282	        <input
283	          data-testid="lineitem-form-qty"
284	          placeholder="How many"
285	          value={qty}
286	          onChange={(e) => setQty(e.target.value)}
287	        />
288	        <input
289	          data-testid="lineitem-form-unit"
290	          placeholder="Unit"
291	          value={unit}
292	          onChange={(e) => setUnit(e.target.value)}
293	        />
294	        <input
295	          data-testid="lineitem-form-unitprice"
296	          placeholder="Price each"
297	          value={unitPrice}
298	          onChange={(e) => setUnitPrice(e.target.value)}
299	        />
300	        <button data-testid="lineitem-form-submit" type="submit">
301	          Add line item
302	        </button>
303	      </form>
304	
305	      <table data-testid="invoice-payments-table">
306	        <tbody>
307	          {payments.map((p) => (
308	            <tr key={p.id} data-testid={`payment-row-${p.id}`}>
309	              <td data-testid="payment-amount">{money(p.amount)}</td>
310	              <td data-testid="payment-date">{p.date}</td>
311	            </tr>
312	          ))}
313	        </tbody>
314	      </table>
315	
316	      <form data-testid="payment-form" onSubmit={submitPayment}>
317	        <input
318	          data-testid="payment-form-amount"
319	          placeholder="Amount paid"
320	          value={paymentAmount}
321	          onChange={(e) => setPaymentAmount(e.target.value)}
322	        />
323	        <input
324	          data-testid="payment-form-date"
325	          type="date"
326	          value={paymentDate}
327	          onChange={(e) => setPaymentDate(e.target.value)}
328	        />
329	        <button data-testid="payment-form-submit" type="submit">
330	          Record payment
331	        </button>
332	      </form>
333	    </section>
334	  );
335	}
336	
337	// Which lifecycle actions an invoice offers depends on where it is in its lifecycle: a draft can be
338	// sent, a sent invoice can be marked paid. Collecting the mapping here keeps the row markup flat and
339	// gives one obvious place to add a new lifecycle action.
340	function InvoiceActions({
341	  invoice,
342	  onOpen,
343	  onSend,
344	  onPay,
345	  onCancel,
346	}: {
347	  invoice: Invoice;
348	  onOpen: () => void;
349	  onSend: () => void;
350	  onPay: () => void;
351	  onCancel: () => void;
352	}) {
353	  return (
354	    <>
355	      <button data-testid={`invoice-open-${invoice.id}`} onClick={onOpen}>
356	        Open
357	      </button>
358	      {invoice.status === 'DRAFT' && (
359	        <button data-testid={`invoice-send-${invoice.id}`} onClick={onSend}>
360	          Send
361	        </button>
362	      )}
363	      {invoice.status === 'SENT' && (
364	        <button data-testid={`invoice-pay-${invoice.id}`} onClick={onPay}>
365	          Mark paid
366	        </button>
367	      )}
368	      {invoice.status === 'SENT' && (
369	        <button data-testid={`invoice-cancel-${invoice.id}`} onClick={onCancel}>
370	          Cancel
371	        </button>
372	      )}
373	    </>
374	  );
375	}
376	
377	// The invoices raised against a project: what they add up to, a form to raise another, and a drill-in
378	// to each invoice's line items and payments. Owns its own invoice state, scoped to the one project.
379	// Whenever the invoices change (a new one raised, a status moved, a line item edited) the owner is
380	// told so figures derived from them — the budget's invoiced/remaining — can be refreshed.
381	function ProjectInvoices({
382	  projectId,
383	  onInvoicesChanged,
384	}: {
385	  projectId: number;
386	  onInvoicesChanged: () => void;
387	}) {
388	  const [invoices, setInvoices] = useState<Invoice[]>([]);
389	  const [amount, setAmount] = useState('');
390	  const [amountError, setAmountError] = useState('');
391	  const [sortByDue, setSortByDue] = useState(false);
392	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
393	
394	  async function load() {
395	    const res = await fetch(`/api/invoices?projectId=${projectId}`);
396	    setInvoices(await res.json());
397	    onInvoicesChanged();
398	  }
399	
400	  useEffect(() => {
401	    void load();
402	  }, [projectId]);
403	
404	  async function submit(e: React.FormEvent) {
405	    e.preventDefault();
406	    const value = Number(amount);
407	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
408	      setAmountError('Amount must be more than zero');
409	      return;
410	    }
411	    setAmountError('');
412	    await fetch('/api/invoices', {
413	      method: 'POST',
414	      headers: { 'Content-Type': 'application/json' },
415	      body: JSON.stringify({ projectId, amount: value }),
416	    });
417	    setAmount('');
418	    await load();
419	  }
420	
421	  // A lifecycle move (send, mark paid, …) is a POST to the matching action route followed by a reload;
422	  // routing them through one place means a new action is one more call site, not new plumbing.
423	  async function transition(id: number, action: 'send' | 'pay' | 'cancel') {
424	    await fetch(`/api/invoices/${id}/${action}`, { method: 'POST' });
425	    await load();
426	  }
427	
428	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
429	  const shownInvoices = sortByDue
430	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
431	    : invoices;
432	
433	  return (
434	    <>
435	      <form data-testid="invoice-form" onSubmit={submit}>
436	        <input
437	          data-testid="invoice-form-amount"
438	          placeholder="Amount"
439	          value={amount}
440	          onChange={(e) => setAmount(e.target.value)}
441	        />
442	        <button data-testid="invoice-form-submit" type="submit">
443	          Add invoice
444	        </button>
445	        {amountError && (
446	          <p data-testid="invoice-form-amount-error" role="alert">
447	            {amountError}
448	          </p>
449	        )}
450	      </form>
451	
452	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
453	        Sort by due date
454	      </button>
455	
456	      {openInvoiceId === null ? (
457	        <>
458	          <table data-testid="project-invoices-table">
459	            <tbody>
460	              {shownInvoices.map((inv) => (
461	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
462	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
